def has_close_elements(numbers: List[float], threshold: float) -> bool:
    numbers.sort()
    for i in range(len(numbers) - 1):
        if abs(numbers[i] - numbers[i + 1]) < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    balance = 0

    for char in paren_string.replace(' ', ''):
        if char == '(':
            balance += 1
            current_group.append(char)
        elif char == ')':
            balance -= 1
            current_group.append(char)
            if balance == 0:
                result.append(''.join(current_group))
                current_group = []

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    mad = sum(abs(x - mean) for x in numbers) / len(numbers)
    return mad

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            for k in range(N):
                l = i + j - k
                if l < 0 or l >= N or grid[i][j] == 0 or grid[k][l] == 0:
                    continue
                if i > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[k][l] * (i != k))
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j] + grid[k][l] * (i != k))
                if j > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[i][j] + grid[k][l] * (j != l))
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j] + grid[k][l] * (j != l))

    return max(0, dp[N-1][N-1][N-1])

