def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        return f"{N}/{level + 1 - N}"
    else:
        return f"{level + 1 - N}/{N}"

def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0:
        return int(num_str)

    def split_and_multiply(start, k):
        if k == 0:
            return int(num_str[start:])
        max_product = 0
        for i in range(start + 1, N - k + 1):
            left = int(num_str[start:i])
            right = split_and_multiply(i, k - 1)
            max_product = max(max_product, left * right)
        return max_product

    return split_and_multiply(0, K)

