def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        parts = isbn.split('-')
        digits = ''.join(parts[:-1]) + parts[-1].replace('X', '10')
        checksum = sum((i + 1) * int(digits[i]) for i in range(10))
        if checksum % 11 == 0:
            return '0'
        elif checksum % 11 == 1:
            return 'X'
        else:
            return str(11 - (checksum % 11))

    provided_checksum = isbn[-1]
    calculated_checksum = calculate_checksum(isbn[:-1] + '0')
    if provided_checksum == calculated_checksum:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + calculated_checksum
        return corrected_isbn

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_separated_pairs(horizontal_aisles, vertical_aisles):
        separated_count = 0
        for (x1, y1, x2, y2) in chatting_pairs:
            h_separated = any(x1 < h < x2 or x2 < h < x1 for h in horizontal_aisles)
            v_separated = any(y1 < v < y2 or y2 < v < y1 for v in vertical_aisles)
            if h_separated or v_separated:
                separated_count += 1
        return separated_count

    best_horizontal = []
    best_vertical = []
    max_separated = 0

    for horizontal_aisles in combinations(range(1, M), K):
        for vertical_aisles in combinations(range(1, N), L):
            separated = count_separated_pairs(horizontal_aisles, vertical_aisles)
            if separated > max_separated:
                max_separated = separated
                best_horizontal = horizontal_aisles
                best_vertical = vertical_aisles

    return (' '.join(map(str, best_horizontal)), ' '.join(map(str, best_vertical)))

def count_passing_ways(n: int, m: int) -> int:
    if m % 2 != 0:
        return 0
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1
    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]
    return dp[m][0]

