def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    dp = [0] * (n + 1)
    for price, importance in items:
        for i in range(n, price - 1, -1):
            dp[i] = max(dp[i], dp[i - price] + price * importance)
    return max(dp)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        coeff_str = str(abs(coeff)) if abs(coeff) != 1 or degree == 0 else ''
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        terms.append(f'{sign}{coeff_str}{var_str}')
    if not terms:
        return '0'
    if terms[0].startswith('+'):
        terms[0] = terms[0][1:]
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def largest_prime_factor(n: int) -> int:
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    count = 0
    for i in range(x, n - k * x + 2):
        count += count_partitions(n - i, k - 1, i)
    return count

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    if last == 0:
        return 1
    count = 1  # The sequence consisting of 'n' itself
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd

    def is_coprime(a, b):
        return gcd(a, b) == 1

    count = 0
    quotient = y0 // x0
    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if is_coprime(a, b):
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos != -1:
                    new_string = current[:pos] + tgt + current[pos + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                start = pos + 1 if pos != -1 else len(current)

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a mapping of transformation rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)

    # BFS to find all unique numbers
    queue = deque([n])
    visited = set([n])

    while queue:
        current = queue.popleft()
        current_str = str(current)

        for i in range(len(current_str)):
            digit = int(current_str[i])
            if digit in transform_map:
                for new_digit in transform_map[digit]:
                    new_number_str = current_str[:i] + str(new_digit) + current_str[i+1:]
                    new_number = int(new_number_str)
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, stmts in statements.items():
        for stmt in stmts:
            if any(day in stmt for day in days_of_week):
                continue
            is_liar = participant in liar_count
            if "guilty" in stmt:
                if (participant == scenario and not is_liar) or (participant != scenario and is_liar):
                    continue
                else:
                    return False
            elif "not guilty" in stmt:
                if (participant == scenario and is_liar) or (participant != scenario and not is_liar):
                    continue
                else:
                    return False
    return True

